set -e
cd "$(dirname "$0")"
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --cert server.pem --key server.key --auth oauthbearer,xoauth2 --user :tok-abc123 --mail-domain example.com --mailbox "ann@example.com:annpass;protocols=http" --mailbox "bob@example.com:bobpass;protocols=http" smtps://127.0.0.1:8080/ imaps://127.0.0.1:8081/ smtp://127.0.0.1:8082/ imap://127.0.0.1:8083/ &
sleep 1
curl -sS --cacert server.pem --crlf -u bob@example.com --oauth2-bearer tok-abc123 --mail-from bob@example.com --mail-rcpt ann@example.com -T lunch.eml -w "%{response_code}\n" smtps://127.0.0.1:8080/example.com --next -sS --cacert server.pem -u ann@example.com --oauth2-bearer tok-abc123 "imaps://127.0.0.1:8081/INBOX;UID=1;SECTION=TEXT"
kill $(jobs -p)
